    /**
     * Tests getting all Quotes.
     *
     * @return    Collection
     */
    public List<Quote> testGetAll() throws Throwable {
    LOGGER.info( "QuoteTest:testGetAll() - Retrieving Collection of Quotes:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all Quote : " );
    List<Quote> collection  = null;

    try {
        // call the static get method on the QuoteService
        collection = service.getAllQuote();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            Quote currEntity  = null;
            Iterator<Quote> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getQuoteId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

